import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../../../Core/Resources/app_icons.dart';import '../../../../Config/Cubit/settings_cubit.dart';import '../../../../generated/l10n.dart';class LanguageList extends StatelessWidget {  const LanguageList({super.key});  @override  Widget build(BuildContext context) {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: _buildLanguageItems(          context, context.read<SettingsCubit>().state.locale),    );  }  List<Widget> _buildLanguageItems(      BuildContext context, Locale selectedLocale) {    final supportedLocales = AppLocalizationDelegate().supportedLocales;    // خريطة تحتوي على أسماء اللغات الكاملة لكل رمز لغة    final languageNames = {      'en': 'English',      'ar': 'العربية',      'fr': 'Français',      'es': 'Español',      'de': 'Deutsch',    };    return List.generate(supportedLocales.length, (index) {      final locale = supportedLocales[index];      bool isSelected = locale == selectedLocale;      return Column(        children: [          InkWell(            onTap: () {              context.read<SettingsCubit>().changeLanguage(locale);            },            child: Padding(              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),              child: Row(                mainAxisAlignment: MainAxisAlignment.spaceBetween,                children: [                  Text(                    languageNames[locale.languageCode] ?? locale.languageCode,                    style: const TextStyle(fontSize: 16),                  ),                  if (isSelected) AppIcons.check,                ],              ),            ),          ),          if (index != supportedLocales.length - 1)            Divider(color: Colors.grey.shade300),        ],      );    });  }}